62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
73	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
74	     * stored lower-cased.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** A well-formed postcode: exactly four digits. */
80	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
81	
82	    /**
83	     * Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. A postcode supplied for an
84	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
85	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
86	     */
87	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
88	        "NSW", new int[] {2000, 2099},
89	        "VIC", new int[] {3000, 3099},
90	        "QLD", new int[] {4000, 4099});
91	
92	    /** Dedicated audit logger; one line is emitted per successful owner create. */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * The maximum number of owners a single city may contain. Once a city already holds this many
97	     * owners, any further create naming that city is rejected as a conflict.
98	     */
99	    private static final int MAX_OWNERS_PER_CITY = 50;
100	
101	    /**
102	     * The maximum number of owners that may be registered in a single day. Once this many owners
103	     * already carry today's registration date, any further create is rejected as too many requests.
104	     */
105	    private static final int MAX_OWNERS_PER_DAY = 100;
106	
107	    /**
108	     * The number of owners that must already be registered on today's business day before a response
109	     * carries a bulk-signup warning. Once more than this many owners already carry today's
110	     * registration date, responses set {@code bulkSignupWarning} true.
111	     */
112	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
113	
114	    private final ClinicService clinicService;
115	
116	    private final OwnerMapper ownerMapper;
117	
118	    private final PetMapper petMapper;
119	
120	    private final VisitMapper visitMapper;
121	
122	    public OwnerRestControllerV1(ClinicService clinicService,
123	                                 OwnerMapper ownerMapper,
124	                                 PetMapper petMapper,
125	                                 VisitMapper visitMapper) {
126	        this.clinicService = clinicService;
127	        this.ownerMapper = ownerMapper;
128	        this.petMapper = petMapper;
129	        this.visitMapper = visitMapper;
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
135	        Collection<Owner> owners;
136	        if (lastName != null) {
137	            owners = this.clinicService.findOwnerByLastName(lastName);
138	        } else {
139	            owners = this.clinicService.findAllOwners();
140	        }
141	        if (owners.isEmpty()) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        OwnerDto ownerDto = toOwnerDto(owner);
156	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
157	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        validateRequiredOwnerFields(ownerFieldsDto);
164	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
165	        LocalDate suppliedOrDefaultDate =
166	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
167	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
168	        rejectDailyLimitExceeded(registrationDate);
169	        rejectCityAtCapacity(ownerFieldsDto.getCity());
170	        HttpHeaders headers = new HttpHeaders();
171	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
172	        validatePostcode(owner.getCity(), owner.getPostcode());
173	        owner.setAddress(normalizeAddress(owner.getAddress()));
174	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
175	        owner.setTelephone(normalizedTelephone);
176	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
177	        owner.setEmail(normalizeEmail(owner.getEmail()));
178	        rejectDuplicateIdentity(owner);
179	        applyPossibleDuplicate(owner);
180	        owner.setRegistrationDate(registrationDate);
181	        owner.setCustomerCode(
182	            generateCustomerCode(owner.getPostcode(), owner.getCity(), normalizedTelephone, owner.getLastName()));
183	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
184	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
185	        this.clinicService.saveOwner(owner);
186	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
187	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
188	        OwnerDto ownerDto = toOwnerDto(owner);
189	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
190	        headers.setLocation(UriComponentsBuilder.newInstance()
191	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
192	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
198	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
199	        if (currentOwner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        currentOwner.setAddress(ownerFieldsDto.getAddress());
203	        currentOwner.setCity(ownerFieldsDto.getCity());
204	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
205	        currentOwner.setLastName(ownerFieldsDto.getLastName());
206	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
207	        this.clinicService.saveOwner(currentOwner);
208	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Transactional
213	    @Override
214	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner == null) {
217	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	        }
219	        this.clinicService.deleteOwner(owner);
220	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
221	    }
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
226	        Owner owner = this.clinicService.findOwnerById(ownerId);
227	        if (owner == null) {
228	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	        }
230	        HttpHeaders headers = new HttpHeaders();
231	        Pet pet = petMapper.toPet(petFieldsDto);
232	        owner.setId(ownerId);
233	        pet.setOwner(owner);
234	        pet.getType().setName(null);
235	        this.clinicService.savePet(pet);
236	        PetDto petDto = petMapper.toPetDto(pet);
237	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
238	            .buildAndExpand(pet.getId()).toUri());
239	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
245	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
246	        if (currentOwner != null) {
247	            Pet currentPet = this.clinicService.findPetById(petId);
248	            if (currentPet != null) {
249	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
250	                currentPet.setName(petFieldsDto.getName());
251	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
252	                this.clinicService.savePet(currentPet);
253	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
254	            }
255	        }
256	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
257	    }
258	
259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
262	        HttpHeaders headers = new HttpHeaders();
263	        Visit visit = visitMapper.toVisit(visitFieldsDto);
264	        Pet pet = new Pet();
265	        pet.setId(petId);
266	        visit.setPet(pet);
267	        this.clinicService.saveVisit(visit);
268	        VisitDto visitDto = visitMapper.toVisitDto(visit);
269	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
270	            .buildAndExpand(visit.getId()).toUri());
271	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
272	    }
273	
274	
275	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
276	    @Override
277	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
278	        Owner owner = this.clinicService.findOwnerById(ownerId);
279	        if (owner != null) {
280	            Pet pet = owner.getPet(petId);
281	            if (pet != null) {
282	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
283	            }
284	        }
285	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
286	    }
287	
288	    /**
289	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
290	     * offending field is collected so the caller learns exactly which values must be supplied.
291	     *
292	     * @param ownerFieldsDto the submitted owner payload
293	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
294	     *         telephone is missing or blank
295	     */
296	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
297	        List<String> missingFields = new ArrayList<>();
298	        if (isBlank(ownerFieldsDto.getFirstName())) {
299	            missingFields.add("firstName");
300	        }
301	        if (isBlank(ownerFieldsDto.getLastName())) {
302	            missingFields.add("lastName");
303	        }
304	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
305	            missingFields.add("address");
306	        }
307	        if (isBlank(ownerFieldsDto.getCity())) {
308	            missingFields.add("city");
309	        }
310	        if (isBlank(ownerFieldsDto.getTelephone())) {
311	            missingFields.add("telephone");
312	        }
313	        if (!missingFields.isEmpty()) {
314	            throw new MissingOwnerFieldsException(missingFields);
315	        }
316	    }
317	
318	    private boolean isBlank(String value) {
319	        return value == null || value.isBlank();
320	    }
321	
322	    /**
323	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
324	     * current date. A registration date may not lie in the future; a value equal to today or in the
325	     * past is accepted, and an absent date is left to default to the server date.
326	     *
327	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
328	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
329	     */
330	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
331	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
332	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
333	        }
334	    }
335	
336	    /**
337	     * Counts the existing owners who, before this create, already share the given first and last name.
338	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
339	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
340	     * case or spacing still count as the same name.
341	     *
342	     * @param firstName the first name of the owner being created
343	     * @param lastName the last name of the owner being created
344	     * @return the number of existing owners sharing both names (zero when none)
345	     */
346	    private int countNamesakes(String firstName, String lastName) {
347	        String first = normalizeHouseholdField(firstName);
348	        String last = normalizeHouseholdField(lastName);
349	        return (int) this.clinicService.findAllOwners().stream()
350	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
351	                && normalizeHouseholdField(existing.getLastName()).equals(last))
352	            .count();
353	    }
354	
355	    /**
356	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
357	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
358	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
359	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
360	     * more owners the create is rejected as a conflict.
361	     *
362	     * @param city the city of the owner being created
363	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
364	     */
365	    /**
366	     * Rejects an owner create once the maximum number of owners have already been registered on the
367	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
368	     * which is always a business day (a weekend effective date is rolled forward to the following
369	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
370	     * business day the create is rejected as too many requests. Because a weekend effective date is
371	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
372	     *
373	     * @param businessDay the adjusted business day the owner being created would be registered on
374	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
375	     */
376	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
377	        long ownersOnDay = this.clinicService.findAllOwners().stream()
378	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
379	            .count();
380	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
381	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
382	        }
383	    }
384	
385	    /**
386	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
387	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
388	     * was supplied on the request or defaulted to the server's current date.
389	     *
390	     * @param date the effective registration date (supplied or defaulted)
391	     * @return the same date when it is a weekday, otherwise the following Monday
392	     */
393	    /**
394	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
395	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
396	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
397	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
398	     *
399	     * @return {@code true} when more than the threshold number of owners are already registered on
400	     *         today's business day, otherwise {@code false}
401	     */
402	    private boolean isBulkSignupWarningActive() {
403	        LocalDate today = toBusinessDay(LocalDate.now());
404	        long ownersToday = this.clinicService.findAllOwners().stream()
405	            .filter(existing -> today.equals(existing.getRegistrationDate()))
406	            .count();
407	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
408	    }
409	
410	    private LocalDate toBusinessDay(LocalDate date) {
411	        return switch (date.getDayOfWeek()) {
412	            case SATURDAY -> date.plusDays(2);
413	            case SUNDAY -> date.plusDays(1);
414	            default -> date;
415	        };
416	    }
417	
418	    private void rejectCityAtCapacity(String city) {
419	        String normalizedCity = normalizeHouseholdField(city);
420	        long ownersInCity = this.clinicService.findAllOwners().stream()
421	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
422	            .count();
423	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
424	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
425	        }
426	    }
427	
428	    /**
429	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
430	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
431	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
432	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). The code carries no
433	     * sequence number; two owners resolve to the same code only when they share a region and produce the
434	     * same telephone-and-last-name hash.
435	     *
436	     * @param postcode the owner's postcode, used first to derive the region
437	     * @param city the owner's city, used to derive the region when the postcode maps to none
438	     * @param normalizedTelephone the owner's normalized (E.164) telephone
439	     * @param lastName the owner's last name
440	     * @return the formatted customer code
441	     */
442	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
443	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
444	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
445	        return region + "-" + hash8;
446	    }
447	
448	    /**
449	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
450	     * customerCode is the owner's customer code and YY is the last two digits of the
451	     * registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
452	     *
453	     * @param customerCode the owner's customer code
454	     * @param registrationDate the owner's registration date
455	     * @return the formatted membership number
456	     */
457	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
458	        String yy = String.format("%02d", registrationDate.getYear() % 100);
459	        return customerCode + "-M" + yy;
460	    }
461	
462	    /**
463	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
464	     * country calling code. Australia ('+61') uses 9 national digits and the North American
465	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
466	     * E.164 length (8 to 15 digits overall).
467	     */
468	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
469	        java.util.Map.of("61", 9, "1", 10);
470	
471	    /**
472	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
473	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
474	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
475	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
476	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
477	     * E.164 string is what gets stored and returned.
478	     *
479	     * @param telephone the raw telephone value from the request
480	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
481	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
482	     *         national number has the wrong length for its country code
483	     */
484	    private String normalizeTelephone(String telephone) {
485	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
486	        String e164;
487	        if (cleaned.startsWith("+")) {
488	            e164 = cleaned;
489	        } else {
490	            String national = cleaned;
491	            if (national.startsWith("0")) {
492	                national = national.substring(1);
493	            }
494	            e164 = "+61" + national;
495	        }
496	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
497	            throw new InvalidOwnerFieldsException(List.of("telephone"));
498	        }
499	        validateNationalNumberLength(e164);
500	        return e164;
501	    }
502	
503	    /**
504	     * Rejects an E.164 telephone whose national number does not have the exact length its country
505	     * calling code requires. The digits after the leading '+' are split into the longest matching
506	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
507	     * code is known and the national number's length differs from the required count the telephone is
508	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
509	     *
510	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
511	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
512	     */
513	    private void validateNationalNumberLength(String e164) {
514	        String digits = e164.substring(1);
515	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
516	            String countryCode = digits.substring(0, codeLength);
517	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
518	            if (requiredNationalLength != null) {
519	                int nationalLength = digits.length() - codeLength;
520	                if (nationalLength != requiredNationalLength) {
521	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
522	                }
523	                return;
524	            }
525	        }
526	    }
527	
528	    /**
529	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
530	     * left unset. When a value is present it must be a syntactically valid address; the normalized
531	     * form stored and returned is the value lower-cased.
532	     *
533	     * @param email the raw email value from the request, or {@code null} when none was supplied
534	     * @return the lower-cased email, or {@code null} when no email was supplied
535	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
536	     */
537	    private String normalizeEmail(String email) {
538	        if (email == null || email.isBlank()) {
539	            return null;
540	        }
541	        if (!EMAIL_PATTERN.matcher(email).matches()) {
542	            throw new InvalidOwnerFieldsException(List.of("email"));
543	        }
544	        return email.toLowerCase(Locale.ROOT);
545	    }
546	
547	    /**
548	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
549	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
550	     * When present it must be exactly four digits and, when the owner's city maps to a known region
551	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
552	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
553	     * region accepts any four-digit postcode.
554	     *
555	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
556	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
557	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
558	     *         for the city's region
559	     */
560	    private void validatePostcode(String city, String postcode) {
561	        if (postcode == null || postcode.isBlank()) {
562	            return;
563	        }
564	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
565	            throw new InvalidOwnerFieldsException(List.of("postcode"));
566	        }
567	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
568	        if (range == null) {
569	            return;
570	        }
571	        int value = Integer.parseInt(postcode);
572	        if (value < range[0] || value > range[1]) {
573	            throw new InvalidOwnerFieldsException(List.of("postcode"));
574	        }
575	    }
576	
577	    /**
578	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
579	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
580	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
581	     * normalized form is what gets stored, returned and used for every address comparison (the
582	     * required-field check, household duplicate detection and the shared household id).
583	     *
584	     * @param address the raw address value from the request, or {@code null}
585	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
586	     */
587	    private String normalizeAddress(String address) {
588	        if (address == null) {
589	            return "";
590	        }
591	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
592	        if (collapsed.isEmpty()) {
593	            return "";
594	        }
595	        String[] tokens = collapsed.split(" ");
596	        for (int i = 0; i < tokens.length; i++) {
597	            switch (tokens[i]) {
598	                case "ST" -> tokens[i] = "STREET";
599	                case "RD" -> tokens[i] = "ROAD";
600	                case "AVE" -> tokens[i] = "AVENUE";
601	                default -> { }
602	            }
603	        }
604	        return String.join(" ", tokens);
605	    }
606	
607	    /**
608	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
609	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
610	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
611	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
612	     * so two members of one household with different telephones have different keys and are both
613	     * allowed; only an owner whose entire key is identical is a duplicate.
614	     *
615	     * @param owner the owner being created, with its telephone, email and householdId already resolved
616	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
617	     */
618	    private void rejectDuplicateIdentity(Owner owner) {
619	        String identityKey = owner.getIdentityKey();
620	        boolean inUse = this.clinicService.findAllOwners().stream()
621	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
622	        if (inUse) {
623	            throw new DuplicateOwnerIdentityException(identityKey);
624	        }
625	    }
626	
627	    /**
628	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
629	     * that shares this owner's last name (compared case-insensitively with collapsed whitespace) and
630	     * postcode but carries a different (normalized) telephone; such an owner is not a hard duplicate
631	     * (its identity key differs) and is still created. When at least one soft match exists,
632	     * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the lowest-id match;
633	     * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
634	     *
635	     * @param owner the owner being created, with its last name, postcode and normalized telephone resolved
636	     */
637	    private void applyPossibleDuplicate(Owner owner) {
638	        String lastName = normalizeHouseholdField(owner.getLastName());
639	        String postcode = owner.getPostcode();
640	        String telephone = owner.getTelephone();
641	        Owner match = null;
642	        if (postcode != null && !postcode.isBlank()) {
643	            match = this.clinicService.findAllOwners().stream()
644	                .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName))
645	                .filter(existing -> postcode.equals(existing.getPostcode()))
646	                .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
647	                .min(java.util.Comparator.comparing(Owner::getId))
648	                .orElse(null);
649	        }
650	        if (match != null) {
651	            owner.setPossibleDuplicate(true);
652	            owner.setPossibleDuplicateOf(match.getId());
653	        } else {
654	            owner.setPossibleDuplicate(false);
655	        }
656	    }
657	
658	    /**
659	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
660	     * last name and a normalized address: last names are compared case-insensitively after whitespace
661	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
662	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
663	     * abbreviation still count as the same household.
664	     * <p>
665	     * When the owner's last name and address already belong to at least one other owner and
666	     * {@code sharesHousehold} is true, every member of the household - the existing owners and this
667	     * joiner - is assigned the same stable {@code householdId}, which is returned on read and forms
668	     * the third component of the {@code identityKey}. When {@code sharesHousehold} is not true, or no
669	     * other owner shares the last name and address, no identifier is assigned. Household membership no
670	     * longer rejects a create on its own; duplicates are detected solely through the identity key.
671	     *
672	     * @param owner the owner being created
673	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
674	     */
675	    /**
676	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
677	     * household member count} for the response.
678	     *
679	     * @param owner the owner to map
680	     * @return the mapped owner DTO
681	     */
682	    private OwnerDto toOwnerDto(Owner owner) {
683	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
684	        return ownerMapper.toOwnerDto(owner);
685	    }
686	
687	    /**
688	     * Counts the members of the given owner's household - the owners that share this owner's
689	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
690	     * is {@code null}) is its own sole member, so the count is one.
691	     *
692	     * @param owner the owner whose household is being sized
693	     * @return the number of owners sharing this owner's household (one when it has no household)
694	     */
695	    private int countHouseholdMembers(Owner owner) {
696	        String householdId = owner.getHouseholdId();
697	        if (householdId == null) {
698	            return 1;
699	        }
700	        return (int) this.clinicService.findAllOwners().stream()
701	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
702	            .count();
703	    }
704	
705	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
706	        String lastName = normalizeHouseholdField(owner.getLastName());
707	        String address = normalizeAddress(owner.getAddress());
708	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
709	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
710	                && normalizeAddress(existing.getAddress()).equals(address))
711	            .toList();
712	        if (housemates.isEmpty()) {
713	            return;
714	        }
715	        if (!Boolean.TRUE.equals(sharesHousehold)) {
716	            return;
717	        }
718	        String householdId = generateHouseholdId(lastName, address);
719	        owner.setHouseholdId(householdId);
720	        for (Owner housemate : housemates) {
721	            if (!householdId.equals(housemate.getHouseholdId())) {
722	                housemate.setHouseholdId(householdId);
723	                this.clinicService.saveOwner(housemate);
724	            }
725	        }
726	    }
727	
728	    /**
729	     * Builds the stable identifier shared by the members of one household. It is derived purely from
730	     * the normalized last name and address, so every owner of a given household deterministically
731	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
732	     * two normalized fields joined by a single space.
733	     *
734	     * @param normalizedLastName the household's last name, already normalized for comparison
735	     * @param normalizedAddress the household's address, already normalized for comparison
736	     * @return the shared household identifier
737	     */
738	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
739	        String key = normalizedLastName + '�' + normalizedAddress;
740	        try {
741	            byte[] digest = MessageDigest.getInstance("SHA-256")
742	                .digest(key.getBytes(StandardCharsets.UTF_8));
743	            StringBuilder hex = new StringBuilder();
744	            for (byte b : digest) {
745	                hex.append(String.format("%02X", b));
746	                if (hex.length() >= 12) {
747	                    break;
748	                }
749	            }
750	            return hex.substring(0, 12);
751	        } catch (NoSuchAlgorithmException e) {
752	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
753	        }
754	    }
755	
756	    /**
757	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
758	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
759	     * the owner's normalized telephone and last name.
760	     *
761	     * @param input the string to digest
762	     * @param length the number of leading upper-case hex characters to return
763	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
764	     */
765	    private String sha256UpperHex(String input, int length) {
766	        try {
767	            byte[] digest = MessageDigest.getInstance("SHA-256")
768	                .digest(input.getBytes(StandardCharsets.UTF_8));
769	            StringBuilder hex = new StringBuilder();
770	            for (byte b : digest) {
771	                hex.append(String.format("%02X", b));
772	                if (hex.length() >= length) {
773	                    break;
774	                }
775	            }
776	            return hex.substring(0, length);
777	        } catch (NoSuchAlgorithmException e) {
778	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
779	        }
780	    }
781	
782	    /**
783	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
784	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
785	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
786	     * expands common abbreviations.
787	     *
788	     * @param value the raw last name, or {@code null}
789	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
790	     */
791	    private String normalizeHouseholdField(String value) {
792	        if (value == null) {
793	            return "";
794	        }
795	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
796	    }
797	}
